"""Real-photo detail crops and saved point states over the source orthophoto."""
from add9_photos import *

def closeup(key,scene):
 c=case('c3');line=line9(key);P=np.array(line['annotation_xyz']);cam=cameras(c['site']);base=json.loads((W9/'c3_camera.json').read_text());cp=W9/'closeup_candidates'/(key+'_'+hashlib.sha256(json.dumps(line['section'],sort_keys=True).encode()).hexdigest()[:16]+'.json');candidates=json.loads(cp.read_text()) if cp.exists() else []
 for j,name in ([] if candidates else enumerate(cam.names)):
  uv,depth=native(P,cam,j);inside=(depth>0)&((uv>=0)&(uv<[cam.w,cam.h])).all(1)
  if not inside.all():continue
  oc,_=visibility(P,cam.centres[j],scene);span=np.ptp(uv,axis=0);width=max(span[0]/.4,span[1]*.75/ .8);height=width/.75;mid=(uv.min(0)+uv.max(0))/2;crop=np.r_[mid-[width/2,height/2],mid+[width/2,height/2]];fits=crop[0]>=0 and crop[1]>=0 and crop[2]<=cam.w and crop[3]<=cam.h
  if not fits:continue
  candidates.append(dict(j=j,name=name,crop=crop.tolist(),native_width=width,line_width_fraction=span[0]/width,visible_fraction=float((~oc).mean()),same_as_whole_photo=name==base['name'],sufficient_native_pixels=bool(width>=804)))
 assert candidates,'No detail candidate';same=[r for r in candidates if r['same_as_whole_photo'] and r['sufficient_native_pixels']];enough=[r for r in candidates if r['sufficient_native_pixels']];pool=same or enough or candidates;best=max(pool,key=lambda r:((r['visible_fraction'] if enough else r['native_width']),-abs(r['line_width_fraction']-.4),r['native_width'],-r['j']));j=best['j'];im,source=undistort_crop(cam,j,np.array(best['crop']),[804,1072]);meta=dict(name=cam.names[j],j=j,parameters=np.r_[cam.p[:4],np.zeros(8)].tolist(),original_FULL_OPENCV_parameters=cam.p.tolist(),R=cam.R[j].tolist(),t=cam.t[j].tolist(),centre=cam.centres[j].tolist(),crop_xyxy_px=best['crop'],source_size_px=[cam.w,cam.h],output_size_px=[804,1072],source=source,calibration_model='undistorted pinhole with original fx fy cx cy',training_camera=True,selection=best);ann=annotation9(c,line,meta,scene);name='c3_edge_closeup_photo' if key=='c3_edge' else 'c3_closeup_photo';save9(im,name,dict(camera=meta,**ann),[meshpath(c,'mvs'),Path(__file__)]);dump(cp,candidates);dump(W9/(name+'_candidates.json'),candidates);print('ADD9_CLOSEUP',key,meta['name'],best,flush=True)

def panels(key,ms):
 c=case('c3');line=line9(key);s=line['section'];a=np.array(s['start']);b=np.array(s['end']);dr=(b-a)/s['length_m'];side=np.array([-dr[1],dr[0]]);center=(a+b)/2;length=s['length_m']+4;width=4.4;W,H=1200,760;row,lab=data(c);P=row['xyz'];delta=P[:,:2]-center;coord=np.c_[delta@dr,delta@side];mask=(abs(coord[:,0])<=length/2)&(abs(coord[:,1])<=width/2);ids=np.flatnonzero(mask);px=np.c_[(coord[mask,0]+length/2)/length*W,(width/2-coord[mask,1])/width*H];path,z,_=ortho(c['site']);xx,yy=np.meshgrid((np.arange(W)+.5)/W*length-length/2,width/2-(np.arange(H)+.5)/H*width);XY=center+xx[:,:,None]*dr+yy[:,:,None]*side;UV=xyuv(XY);mapx=((UV[:,:,0]-z['u0'])/z['res']-.5).astype('f4');mapy=((UV[:,:,1]-z['v0'])/z['res']-.5).astype('f4');base=ImageEnhance.Color(Image.fromarray(cv2.remap(z['rgb'],mapx,mapy,cv2.INTER_CUBIC,borderMode=cv2.BORDER_CONSTANT,borderValue=(255,255,255)))).enhance(.3)
 def pix(q):q=np.array(q)[:,:2]-center;return np.c_[(q@dr+length/2)/length*W,(width/2-q@side)/width*H]
 linepx=pix(line['annotation_xyz']);corners=box9(c,s,half=2.2);meta=dict(case=c['id'],bounds_local_xy=corners[:,:2].tolist(),center_local_xy=center.tolist(),horizontal_direction_unit_xy=dr.tolist(),vertical_up_direction_unit_xy=side.tolist(),extent_m=[length,width],pixel_size_m=[length/W,width/H],saturation=.3,A_px=linepx[0].tolist(),Aprime_px=linepx[-1].tolist(),line_polyline_px=linepx.tolist(),line_occluded=None,line_occlusion_note='orthophoto depth absent; point-state panel is a planimetric plot of all requested rows',line_points_inside_image=(((linepx>=0)&(linepx<[W,H])).all(1)).tolist(),box_corners_px=pix(corners).tolist(),point_colors=A9['point_colors'],other_case_color='#C9CED6')
 for m in ms:
  zz=loadz(scorepath(c,m),['row_s'])['row_s'][ids];states=status(zz,row['row_tau_m'][ids]);target=lab[ids]==2;im=circles(base,px,lab[ids],{str(k):'#C9CED6' for k in range(-5,6)},[k for k in range(-5,6) if k!=2],radius=1.8,alpha=1);im=circles(im,px[target],states[target],A9['point_colors'],['in','far','none'],radius=3.2,alpha=1);points=[dict(row_id=int(r),pixel_xy=q.tolist(),case_id=int(lab[r]),status=str(st),signed_distance_m=float(v) if np.isfinite(v) else None,tau_m=float(row['row_tau_m'][r])) for r,q,st,v in zip(ids,px,states,zz)];counts={k:int((target&(states==k)).sum()) for k in ['in','far','none']};save9(im,key+'_points_'+m,dict(**meta,method=m,n_case2=int(target.sum()),n_other=int((~target).sum()),case2_state_counts=counts,points=points,saved_scores_reused=True),[path,root_of(c)/'rows.npz',root_of(c)/'stage1_cells.npz',scorepath(c,m)]);print('ADD9_POINTS',key,m,counts,flush=True)

def main():
 c=case('c3');p=meshpath(c,'mvs');V,F=read_surface(p);sc=MeshScene(V,F);del V,F;gc.collect()
 for key in (['c3_edge'] if 'edgeonly' in sys.argv else ['c3','c3_edge']):
  closeup(key,sc)
