 cam=json.loads((W9/'c3_camera.json').read_text());ann=annotation9(c,line9('c3_edge'),cam,sc);dump(F9/'c3_edge_photo_line.json',record('c3_edge_photo_line',dict(camera=cam,reference_images=['c2_photo.png','c3_photo.png'],line_drawn=False,box_drawn=False,**ann),[p,F9/'c3_photo.png',W9/'edge_selected.json']))
